const menu=document.querySelector('.mobileNav'),toggle=document.querySelector('.menuButton'),main=document.querySelector('main'),footer=document.querySelector('footer');
function setMenu(open){document.body.style.overflow=open?'hidden':'';menu.hidden=!open;toggle.textContent=open?'Close':'Menu';toggle.setAttribute('aria-expanded',String(open));main.inert=open;footer.inert=open;document.querySelector('.logoLink').inert=open;document.querySelector('.headerRfq').inert=open;if(open)menu.querySelector('a').focus();else toggle.focus({preventScroll:true});}
toggle.addEventListener('click',()=>setMenu(menu.hidden));
menu.querySelectorAll('a').forEach(a=>a.addEventListener('click',()=>setMenu(false)));
document.addEventListener('keydown',e=>{if(menu.hidden)return;if(e.key==='Escape'){e.preventDefault();setMenu(false)}if(e.key==='Tab'){const nodes=[toggle,...menu.querySelectorAll('a')],first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
window.matchMedia('(min-width:1101px)').addEventListener('change',e=>{if(e.matches&&!menu.hidden)setMenu(false)});
